import unittest

from hourglass.rounding import round_labels
from hourglass.parsing import parse_span


class RoundLabelTests(unittest.TestCase):
    def labels(self, texts, step):
        spans = [parse_span(text) for text in texts]
        return round_labels(spans, step)

    def test_exact_times_are_kept(self):
        self.assertEqual(
            self.labels(["09:00-17:15"], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_start_and_end_snap_to_nearest(self):
        self.assertEqual(
            self.labels(["09:04-17:11"], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            self.labels(["09:07-10:22"], 15),
            ["09:00-10:15 (1h 15m)"],
        )
        self.assertEqual(
            self.labels(["09:08-10:23"], 15),
            ["09:15-10:30 (1h 15m)"],
        )

    def test_hour_step(self):
        self.assertEqual(
            self.labels(["08:29-12:30"], 60),
            ["08:00-13:00 (5h 0m)"],
        )

    def test_end_of_day(self):
        self.assertEqual(
            self.labels(["23:00-24:00"], 30),
            ["23:00-24:00 (1h 0m)"],
        )

    def test_one_label_per_span(self):
        texts = ["08:00-12:00", "13:00-17:00"]
        result = self.labels(texts, 5)
        self.assertEqual(len(result), 2)

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        span = parse_span("09:00-10:00")
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([span], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)
